#[derive(Clone)]
pub struct Store {
    connection: Arc<Mutex<Connection>>,
}

#[derive(Debug, Error)]
pub enum StoreError {
    #[error("database error: {0}")]
    Database(#[from] db::Error),
    #[error("storage I/O error: {0}")]
    Io(#[from] std::io::Error),
    #[error("store lock was poisoned")]
    LockPoisoned,
    #[error("{0} not found")]
    NotFound(&'static str),
    #[error("{0}")]
    Validation(String),
    #[error("{0}")]
    Conflict(String),
    #[error("{0}")]
    Unauthorized(String),
    #[error("document was not quoted for this query")]
    DocumentNotQuoted,
}

