fn new_id(prefix: &str) -> String {
    let mut entropy = [0_u8; 16];
    OsRng.fill_bytes(&mut entropy);
    let suffix = entropy
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    format!("{prefix}_{suffix}")
}

fn handle_from_id(id: &str) -> String {
    format!("MD{}", &sha256_hex(id)[..10]).to_uppercase()
}

fn slug(value: &str) -> String {
    value
        .to_lowercase()
        .chars()
        .map(|character| {
            if character.is_alphanumeric() {
                character
            } else {
                '-'
            }
        })
        .collect::<String>()
        .split('-')
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join("-")
}

fn now_ms() -> u64 {
    monotonic_unix_time_ms()
}

fn as_i64(value: u64) -> Result<i64, StoreError> {
    i64::try_from(value)
        .map_err(|_| StoreError::Validation("numeric value is too large".to_owned()))
}

fn as_u64(value: i64) -> db::Result<u64> {
    u64::try_from(value).map_err(|error| db::Error::Conversion(error.to_string()))
}

fn operations_status_counts(
    connection: &Connection,
    query: &str,
) -> Result<Vec<OperationsStatusCount>, StoreError> {
    let mut statement = connection.prepare(query)?;
    let rows = statement
        .query_map(params![], |row| {
            Ok(OperationsStatusCount {
                status: row.get(0)?,
                count: as_u64(row.get(1)?)?,
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    Ok(rows)
}

fn as_usize(value: i64) -> db::Result<usize> {
    usize::try_from(value).map_err(|error| db::Error::Conversion(error.to_string()))
}

fn add_column_if_missing(
    connection: &Connection,
    table: &str,
    column: &str,
    definition: &str,
) -> Result<(), StoreError> {
    if !connection.column_exists(table, column)? {
        connection.execute_batch(&format!(
            "ALTER TABLE {table} ADD COLUMN {column} {definition};"
        ))?;
    }
    Ok(())
}

fn valid_email(email: &str) -> bool {
    let mut parts = email.split('@');
    let local = parts.next().unwrap_or_default();
    let domain = parts.next().unwrap_or_default();
    !local.is_empty()
        && local.len() <= 64
        && domain.len() <= 255
        && domain.contains('.')
        && !domain.starts_with('.')
        && !domain.ends_with('.')
        && parts.next().is_none()
        && !email.chars().any(char::is_whitespace)
}

