    #[test]
    fn email_outbox_lease_prevents_duplicate_delivery_and_recovers_crashes() {
        let store = Store::in_memory().unwrap();
        let email = "email-race@example.com";
        store.register_user(email, "irrelevant-test-hash").unwrap();
        store
            .queue_password_reset(
                email,
                &"1".repeat(64),
                "first-reset-token-with-at-least-32-bytes",
                "https://openshelf.example",
            )
            .unwrap();
        let email_id = store.pending_emails(10).unwrap()[0].id.clone();

        // Two independent application tasks begin from the same queue view.
        // The database state transition, rather than a process-local flag,
        // must choose the one task allowed to contact the provider.
        let barrier = Arc::new(Barrier::new(2));
        let workers = ["email-worker-race-alpha", "email-worker-race-bravo"].map(|worker_id| {
            let worker_store = store.clone();
            let barrier = Arc::clone(&barrier);
            std::thread::spawn(move || {
                barrier.wait();
                (
                    worker_id,
                    worker_store
                        .lease_pending_emails(worker_id, 10, 60_000)
                        .unwrap(),
                )
            })
        });
        let outcomes = workers.map(|worker| worker.join().expect("email worker should not panic"));
        assert_eq!(
            outcomes
                .iter()
                .map(|(_, emails)| emails.len())
                .sum::<usize>(),
            1,
            "one outbox row may be handed to only one provider caller"
        );
        let winner = outcomes
            .iter()
            .find(|(_, emails)| !emails.is_empty())
            .map(|(worker_id, _)| *worker_id)
            .unwrap();
        let loser = outcomes
            .iter()
            .find(|(_, emails)| emails.is_empty())
            .map(|(worker_id, _)| *worker_id)
            .unwrap();
        assert!(matches!(
            store.mark_email_failed(&email_id, loser, "stale worker response"),
            Err(StoreError::Conflict(_))
        ));
        store.mark_email_delivered(&email_id, winner).unwrap();
        let delivered: (String, i64, String, String, String) = store
            .connection()
            .unwrap()
            .query_row(
                "SELECT status, attempts, recipient, subject, body
                 FROM email_outbox WHERE id = ?1",
                [&email_id],
                |row| {
                    Ok((
                        row.get(0)?,
                        row.get(1)?,
                        row.get(2)?,
                        row.get(3)?,
                        row.get(4)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(
            delivered,
            (
                "delivered".to_owned(),
                1,
                String::new(),
                String::new(),
                String::new()
            )
        );

        // Model the dangerous crash point: the provider call may have
        // succeeded, but the process died before recording its response.
        // A replacement gets the same durable email id (the provider's
        // idempotency key), while the old worker loses all write authority.
        store
            .queue_password_reset(
                email,
                &"2".repeat(64),
                "second-reset-token-with-at-least-32-bytes",
                "https://openshelf.example",
            )
            .unwrap();
        let crashed_email = store.pending_emails(10).unwrap()[0].id.clone();
        let crashed_worker = "email-worker-before-crash";
        assert_eq!(
            store
                .lease_pending_emails(crashed_worker, 10, 60_000)
                .unwrap()
                .len(),
            1
        );
        store
            .connection()
            .unwrap()
            .execute(
                "UPDATE email_outbox SET lease_expires_at = ?1 WHERE id = ?2",
                params![i64::MAX, crashed_email],
            )
            .unwrap();
        assert!(
            store
                .lease_pending_emails("email-worker-hidden-by-future", 10, 60_000)
                .unwrap()
                .is_empty()
        );
        assert!(matches!(
            store.ready(),
            Err(StoreError::Conflict(message)) if message.contains("email delivery")
        ));
        store
            .connection()
            .unwrap()
            .execute(
                "UPDATE email_outbox SET lease_expires_at = 0 WHERE id = ?1",
                [&crashed_email],
            )
            .unwrap();
        let recovery_worker = "email-worker-after-crash";
        let recovered = store
            .lease_pending_emails(recovery_worker, 10, 60_000)
            .unwrap();
        assert_eq!(recovered.len(), 1);
        assert_eq!(recovered[0].id, crashed_email);
        assert!(matches!(
            store.mark_email_delivered(&crashed_email, crashed_worker),
            Err(StoreError::Conflict(_))
        ));
        store
            .mark_email_delivered(&crashed_email, recovery_worker)
            .unwrap();
        let attempts: i64 = store
            .connection()
            .unwrap()
            .query_row(
                "SELECT attempts FROM email_outbox WHERE id = ?1",
                [&crashed_email],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(attempts, 2);

        // A torn legacy/manual row can have `sending` without any expiry.
        // Treat it as abandoned rather than hiding it forever.
        store
            .queue_password_reset(
                email,
                &"3".repeat(64),
                "third-reset-token-with-at-least-32-bytes",
                "https://openshelf.example",
            )
            .unwrap();
        let orphaned_email = store.pending_emails(10).unwrap()[0].id.clone();
        store
            .connection()
            .unwrap()
            .execute(
                "UPDATE email_outbox
                 SET status = 'sending', lease_owner = 'orphaned-worker',
                     lease_expires_at = NULL
                 WHERE id = ?1",
                [&orphaned_email],
            )
            .unwrap();
        let orphan_recovery = store
            .lease_pending_emails("email-worker-orphan-recovery", 10, 60_000)
            .unwrap();
        assert_eq!(orphan_recovery.len(), 1);
        assert_eq!(orphan_recovery[0].id, orphaned_email);

        // A provider that stays broken must not leave a reset URL and email
        // address in a queue state that no worker will ever inspect again.
        store
            .mark_email_delivered(&orphaned_email, "email-worker-orphan-recovery")
            .unwrap();
        store
            .queue_password_reset(
                email,
                &"4".repeat(64),
                "fourth-reset-token-with-at-least-32-bytes",
                "https://openshelf.example",
            )
            .unwrap();
        let exhausted_email = store.pending_emails(10).unwrap()[0].id.clone();
        for attempt in 1..=5 {
            let worker = format!("email-failure-worker-{attempt}");
            let leased = store.lease_pending_emails(&worker, 10, 60_000).unwrap();
            assert_eq!(leased.len(), 1);
            assert_eq!(leased[0].id, exhausted_email);
            assert_eq!(
                store
                    .mark_email_failed(&exhausted_email, &worker, "provider unavailable")
                    .unwrap(),
                attempt == 5
            );
        }
        assert!(store.pending_emails(10).unwrap().is_empty());
        let exhausted: (String, i64, String, String, String, String) = store
            .connection()
            .unwrap()
            .query_row(
                "SELECT status, attempts, recipient, subject, body, last_error
                 FROM email_outbox WHERE id = ?1",
                [&exhausted_email],
                |row| {
                    Ok((
                        row.get(0)?,
                        row.get(1)?,
                        row.get(2)?,
                        row.get(3)?,
                        row.get(4)?,
                        row.get(5)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(
            exhausted,
            (
                "exhausted".to_owned(),
                5,
                String::new(),
                String::new(),
                String::new(),
                "provider unavailable".to_owned(),
            )
        );
    }

    #[test]
    fn agent_reuses_only_a_high_confidence_paid_memory() {
        let store = Store::in_memory().unwrap();
        let first = create_svalbard_call(&store, "first-agent-buyer", 1);
        let submitted = submit(&store, &first.id, "agent-contributor", strong_answer()).unwrap();
        assert_eq!(submitted.memory.status, "settled");
        let reliability_before_reuse =
            super::author_reliability_readonly(&store.connection().unwrap(), "agent-contributor")
                .unwrap();
        store
            .update_preferences(
                "agent-contributor",
                &UpdatePreferencesRequest {
                    auto_match: Some(true),
                    agents: Some(true),
                    browser_alerts: None,
                    email_alerts: None,
                },
            )
            .unwrap();

        let second = create_svalbard_call(&store, "second-agent-buyer", 1);
        assert_eq!(second.answered, 1);
        assert_eq!(second.status, "filled");
        let auto = store
            .list_memory("agent-contributor")
            .unwrap()
            .into_iter()
            .find(|entry| entry.via == "Auto-match")
            .expect("near-identical call should reuse the existing memory");
        assert_eq!(auto.answer, strong_answer());
        assert_eq!(auto.earned, second.unit_price);
        assert_eq!(auto.source_ids, vec![submitted.memory.id]);
        assert_eq!(auto.memory_type, "reuse");
        assert_eq!(
            super::author_reliability_readonly(&store.connection().unwrap(), "agent-contributor",)
                .unwrap(),
            reliability_before_reuse,
        );
        assert!(matches!(
            store.set_memory_locked("agent-contributor", &auto.id, true),
            Err(StoreError::Conflict(message)) if message.contains("source passage")
        ));
        assert!(matches!(
            store.correct_memory(
                "agent-contributor",
                &auto.id,
                &CorrectMemoryRequest {
                    answer: strong_answer().to_owned(),
                },
            ),
            Err(StoreError::Conflict(message)) if message.contains("original memory")
        ));

        // Existing databases may contain auto-match rows written before reuse
        // had its own type. Migration reclassifies them and repairs document
        // reliability using only firsthand observations.
        let connection = store.connection().unwrap();
        connection
            .execute(
                "UPDATE memory_entries SET memory_type = 'observation' WHERE id = ?1",
                [&auto.id],
            )
            .unwrap();
        connection
            .execute(
                "UPDATE documents SET reliability_score = 0.98
                 WHERE author_id = 'agent-contributor'",
                params![],
            )
            .unwrap();
        super::backfill_auto_match_reuse(&connection).unwrap();
        let (migrated_type, repaired_reliability): (String, f32) = connection
            .query_row(
                "SELECT m.memory_type, d.reliability_score
                 FROM memory_entries m JOIN documents d ON d.id = m.document_id
                 WHERE m.id = ?1",
                [&auto.id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(migrated_type, "reuse");
        assert_eq!(repaired_reliability, reliability_before_reuse);
    }

    #[test]
    fn paid_reuse_does_not_inflate_observation_count_or_trigger_reflection() {
        let store = Store::in_memory().unwrap();
        let contributor = "reuse-is-not-observation";
        let first = create_svalbard_call(&store, "first-reuse-buyer", 1);
        submit(&store, &first.id, contributor, strong_answer()).unwrap();
        store
            .update_preferences(
                contributor,
                &UpdatePreferencesRequest {
                    auto_match: Some(true),
                    agents: Some(true),
                    browser_alerts: None,
                    email_alerts: None,
                },
            )
            .unwrap();

        let second = create_svalbard_call(&store, "second-reuse-buyer", 1);
        assert_eq!(second.status, "filled");

        store
            .update_preferences(
                contributor,
                &UpdatePreferencesRequest {
                    auto_match: Some(true),
                    agents: Some(false),
                    browser_alerts: None,
                    email_alerts: None,
                },
            )
            .unwrap();
        let third = create_svalbard_call(&store, "third-reuse-buyer", 1);
        let distinct_answer = "During February 2025 near Ny-Alesund I used a pair of insulated La Sportiva boots for an 8 hour sensor deployment. The rigid sole gripped the icy trail well, while a dry spare sock and vapor barrier prevented the damp liner from chilling my feet on the return walk.";
        submit(&store, &third.id, contributor, distinct_answer).unwrap();

        let memories = store.list_memory(contributor).unwrap();
        assert_eq!(
            memories
                .iter()
                .filter(|memory| memory.memory_type == "observation")
                .count(),
            2,
        );
        assert_eq!(
            memories
                .iter()
                .filter(|memory| memory.memory_type == "reuse")
                .count(),
            1,
        );
        assert!(
            memories
                .iter()
                .all(|memory| memory.memory_type != "reflection")
        );
    }

    #[test]
    fn ai_liquidity_is_ephemeral_and_never_enters_the_human_index() {
        let store = Store::in_memory().unwrap();
        let documents_before = store.documents().unwrap().len();
        let question = "How should someone generally evaluate a new kind of local workspace?";
        let resolver = Resolver::new(store.documents().unwrap());
        let response = resolver
            .resolve(ResolveQuestionRequest {
                question: question.to_owned(),
                requested_documents: 5,
                budget_krw: None,
                filters: SearchFilters::default(),
            })
            .unwrap();
        assert_eq!(response.liquidity_state, LiquidityState::AiLiquidityOnly);
        assert!(response.ai_baseline_eligible);
        let token_hash = "ab".repeat(32);
        store
            .record_resolution(question, &response, Some(&token_hash))
            .unwrap();
        let (_, cached) = store
            .ai_baseline_context(&response.query_id, &token_hash)
            .unwrap();
        assert!(cached.is_none());

        let baseline = store
            .record_ai_baseline(
                &response.query_id,
                &token_hash,
                &AiBaselineDraft {
                    orientation: "Workspaces are generally evaluated through access, comfort, and operating rules."
                        .to_owned(),
                    general_points: vec!["Compare noise, seating, power, and time limits."
                        .to_owned()],
                    human_gaps: vec![
                        "Recent crowding and staff practice require a firsthand visitor."
                            .to_owned(),
                    ],
                    questions_for_people: vec![
                        "When did you last stay there for more than two hours?".to_owned(),
                    ],
                },
                &AiArtifactMetadata {
                    model: "gemini-test",
                    mode: "test",
                    policy_version: "general-liquidity-v1",
                    ttl_ms: 60_000,
                },
            )
            .unwrap();
        assert_eq!(baseline.price_krw, 0);
        assert!(!baseline.sellable);
        assert!(!baseline.counts_as_human_coverage);
        assert_eq!(store.documents().unwrap().len(), documents_before);

        let (_, cached) = store
            .ai_baseline_context(&response.query_id, &token_hash)
            .unwrap();
        assert_eq!(cached.unwrap().id, baseline.id);
    }

    #[test]
    fn model_provider_fence_survives_response_loss_and_caps_novel_inputs() {
        let path = PathBuf::from(format!(
            "/tmp/openshelf-ai-provider-fence-{}-{}.db",
            std::process::id(),
            now_ms()
        ));
        let first = Store::open(&path).unwrap();
        let second = Store::open(&path).unwrap();
        let barrier = Arc::new(Barrier::new(2));
        let input = "a".repeat(64);
        let synthesis_handles = vec!["PARISR_12".to_owned()];
        let workers = [first, second]
            .into_iter()
            .map(|store| {
                let barrier = Arc::clone(&barrier);
                let input = input.clone();
                let synthesis_handles = synthesis_handles.clone();
                std::thread::spawn(move || {
                    barrier.wait();
                    store.claim_ai_generation(
                        "synthesis",
                        "query-paid-once",
                        &input,
                        &synthesis_handles,
                    )
                })
            })
            .collect::<Vec<_>>();
        let claims = workers
            .into_iter()
            .map(|worker| worker.join().unwrap().unwrap())
            .collect::<Vec<_>>();
        assert_eq!(
            claims
                .iter()
                .filter(|claim| matches!(claim, AiGenerationClaim::Acquired { .. }))
                .count(),
            1,
            "two API processes may race, but only one may contact the model provider"
        );
        assert_eq!(
            claims
                .iter()
                .filter(|claim| matches!(claim, AiGenerationClaim::Suppressed))
                .count(),
            1
        );

        // Model the worst crash point: the provider accepted the request, but
        // the API process died before it could persist or return the response.
        // A fresh process must preserve the ambiguous fence rather than buy it
        // again merely because the client retries.
        let restarted = Store::open(&path).unwrap();
        assert_eq!(
            restarted
                .claim_ai_generation("synthesis", "query-paid-once", &input, &synthesis_handles,)
                .unwrap(),
            AiGenerationClaim::Suppressed
        );

        // Two machines can disagree about the UTC day at midnight. Move a
        // real claimed attempt into the preceding budget window, then prove a
        // fresh caller in the current window still cannot buy the exact input.
        let boundary_input = "e".repeat(64);
        let boundary_window = match restarted
            .claim_ai_generation(
                "synthesis",
                "query-midnight-skew",
                &boundary_input,
                &synthesis_handles,
            )
            .unwrap()
        {
            AiGenerationClaim::Acquired { window_started_at } => window_started_at,
            claim => panic!("the boundary fixture should acquire once: {claim:?}"),
        };
        let prior_window = boundary_window.saturating_sub(AI_GENERATION_BUDGET_WINDOW_MS);
        restarted
            .connection()
            .unwrap()
            .execute(
                "UPDATE ai_generation_attempts SET window_started_at = ?1
                 WHERE artifact_kind = 'synthesis' AND scope_id = 'query-midnight-skew'",
                [as_i64(prior_window).unwrap()],
            )
            .unwrap();
        restarted
            .connection()
            .unwrap()
            .execute(
                "UPDATE ai_generation_budgets SET window_started_at = ?1
                 WHERE artifact_kind = 'synthesis' AND scope_id = 'query-midnight-skew'",
                [as_i64(prior_window).unwrap()],
            )
            .unwrap();
        assert_eq!(
            restarted
                .claim_ai_generation(
                    "synthesis",
                    "query-midnight-skew",
                    &boundary_input,
                    &synthesis_handles,
                )
                .unwrap(),
            AiGenerationClaim::Suppressed,
            "midnight window skew must not create a second exact provider call"
        );

        let second_input = "b".repeat(64);
        let second_window = match restarted
            .claim_ai_generation(
                "synthesis",
                "query-paid-once",
                &second_input,
                &synthesis_handles,
            )
            .unwrap()
        {
            AiGenerationClaim::Acquired { window_started_at } => window_started_at,
            claim => panic!("a distinct paid-evidence input should fit the budget: {claim:?}"),
        };
        let durable_response = serde_json::json!({
            "answer": "The paid reports agree on the operating constraint [PAID_1].",
            "confidence": 0.8,
            "consensus": ["The constraint appeared in the opened evidence."],
            "disagreements": [],
            "usedHandles": ["PAID_1"],
            "contributions": [{
                "handle": "PAID_1",
                "score": 0.8,
                "reason": "Directly supports the bounded conclusion."
            }],
            "model": "gemini-test",
            "mode": "vertex"
        })
        .to_string();
        restarted
            .complete_ai_generation(
                "synthesis",
                "query-paid-once",
                &second_input,
                second_window,
                Some(&durable_response),
            )
            .unwrap();
        assert_eq!(
            restarted
                .claim_ai_generation(
                    "synthesis",
                    "query-paid-once",
                    &second_input,
                    &synthesis_handles,
                )
                .unwrap(),
            AiGenerationClaim::Cached(durable_response)
        );

        assert!(matches!(
            restarted
                .claim_ai_generation(
                    "synthesis",
                    "query-paid-once",
                    &"c".repeat(64),
                    &synthesis_handles,
                )
                .unwrap(),
            AiGenerationClaim::Acquired { .. }
        ));
        assert_eq!(
            restarted
                .claim_ai_generation(
                    "synthesis",
                    "query-paid-once",
                    &"d".repeat(64),
                    &synthesis_handles,
                )
                .unwrap(),
            AiGenerationClaim::Suppressed,
            "changing handle combinations must not evade the per-query provider budget"
        );
        restarted.ready().unwrap();
        drop(restarted);
        for suffix in ["", "-wal", "-shm"] {
            let target = PathBuf::from(format!("{}{suffix}", path.display()));
            if target.exists() {
                std::fs::remove_file(&target).unwrap();
            }
        }
    }

    #[test]
    fn query_payment_capability_expires_server_side() {
        let store = Store::in_memory().unwrap();
        let question = "How should someone generally evaluate an unfamiliar local workspace?";
        let response = Resolver::new(store.documents().unwrap())
            .resolve(ResolveQuestionRequest {
                question: question.to_owned(),
                requested_documents: 5,
                budget_krw: None,
                filters: SearchFilters::default(),
            })
            .unwrap();
        let token_hash = "ef".repeat(32);
        store
            .record_resolution(question, &response, Some(&token_hash))
            .unwrap();
        store
            .connection()
            .unwrap()
            .execute(
                "UPDATE queries SET payment_token_expires_at = 0 WHERE id = ?1",
                [response.query_id.as_str()],
            )
            .unwrap();
        assert!(matches!(
            store.ai_baseline_context(&response.query_id, &token_hash),
            Err(StoreError::Unauthorized(_))
        ));
    }

    #[test]
    fn ai_liquidity_metrics_keep_ai_out_of_priced_inventory_and_authority() {
        let store = Store::in_memory().unwrap();
        ensure_user(&store, "metrics-admin");
        ensure_user(&store, "metrics-user");
        store.set_user_role("metrics-admin", "admin").unwrap();
        assert!(matches!(
            store.ai_liquidity_metrics("metrics-user"),
            Err(StoreError::Unauthorized(_))
        ));
        let metrics = store.ai_liquidity_metrics("metrics-admin").unwrap();
        assert_eq!(metrics.priced_ai_documents, 0);
        assert_eq!(metrics.ai_authority_edges, 0);
        assert!(metrics.human_documents > 0);
        assert!(metrics.starter_to_human_document_rate >= 0.0);
        assert!(metrics.starter_to_human_document_rate <= 1.0);
    }

    #[test]
    fn operations_snapshot_is_admin_only_and_aggregate_only() {
        let store = Store::in_memory().unwrap();
        ensure_user(&store, "operations-admin");
        ensure_user(&store, "operations-user");
        store.set_user_role("operations-admin", "admin").unwrap();

        assert!(matches!(
            store.admin_operations_snapshot("operations-user"),
            Err(StoreError::Unauthorized(_))
        ));

        let snapshot = store.admin_operations_snapshot("operations-admin").unwrap();
        assert!(snapshot.marketplace.human_documents > 0);
        assert!(snapshot.marketplace.independent_contributors > 0);
        assert_eq!(snapshot.ai_liquidity.priced_ai_documents, 0);
        assert_eq!(snapshot.ai_liquidity.ai_authority_edges, 0);

        let serialized = serde_json::to_string(&snapshot).unwrap();
        for forbidden in [
            "walletAddress",
            "transactionSignature",
            "sessionToken",
            "documentText",
            "privateKey",
            "credential",
        ] {
            assert!(!serialized.contains(forbidden));
        }
    }

    #[test]
    fn sufficient_human_supply_disables_ai_liquidity_even_when_budget_blocks_purchase() {
        let store = Store::in_memory().unwrap();
        let question = "Where do Seongsu residents eat weekday lunch without a long queue?";
        let response = Resolver::new(store.documents().unwrap())
            .resolve(ResolveQuestionRequest {
                question: question.to_owned(),
                requested_documents: 1,
                budget_krw: Some(0),
                filters: SearchFilters::default(),
            })
            .unwrap();
        assert_eq!(response.liquidity_state, LiquidityState::HumanCovered);
        assert!(!response.ai_baseline_eligible);
        let token_hash = "cd".repeat(32);
        store
            .record_resolution(question, &response, Some(&token_hash))
            .unwrap();
        let error = store
            .ai_baseline_context(&response.query_id, &token_hash)
            .unwrap_err();
        assert!(error.to_string().contains("AI liquidity is disabled"));
    }

    #[test]
    fn ai_starter_is_only_a_prompt_until_a_human_creates_the_sellable_document() {
        let store = Store::in_memory().unwrap();
        onboard(&store, "starter-contributor");
        let documents_before = store.documents().unwrap().len();
        let drafts = vec![
            ShelfStarterDraft {
                prompt: "Think of your latest winter field trip. Which boots did you use, when, and what changed after several hours?".to_owned(),
                rationale: "A delayed field outcome requires firsthand experience.".to_owned(),
                category: "travel".to_owned(),
            },
            ShelfStarterDraft {
                prompt: "Describe the last on-call alert you removed and what happened during the following 30 days.".to_owned(),
                rationale: "The operational tradeoff cannot be generated honestly.".to_owned(),
                category: "engineering".to_owned(),
            },
            ShelfStarterDraft {
                prompt: "What changed after you moved away from Seoul while keeping the same work, including one concrete weekly routine?".to_owned(),
                rationale: "A lived routine adds evidence beyond general guidance.".to_owned(),
                category: "life".to_owned(),
            },
        ];
        let starters = store
            .record_shelf_starters(
                "starter-contributor",
                &drafts,
                "gemini-test",
                "test",
                "general-liquidity-v1",
                60_000,
            )
            .unwrap();
        assert_eq!(starters.len(), 3);
        assert!(starters.iter().all(|starter| !starter.buyer_waiting));
        assert!(
            starters
                .iter()
                .all(|starter| starter.guaranteed_reward_krw == 0)
        );
        assert_eq!(store.documents().unwrap().len(), documents_before);

        let travel = starters
            .iter()
            .find(|starter| starter.category == "travel")
            .unwrap();
        let submitted = store
            .submit_shelf_starter_answer("starter-contributor", &travel.id, strong_answer(), 300)
            .unwrap();
        assert_eq!(submitted.memory.via, "Shelf starter");
        assert_eq!(submitted.memory.earned, 0);
        assert_eq!(store.documents().unwrap().len(), documents_before + 1);
        assert!(
            !store
                .list_shelf_starters("starter-contributor")
                .unwrap()
                .iter()
                .any(|starter| starter.id == travel.id)
        );
    }

    #[test]
    fn sqlite_data_survives_reopen() {
        let path = PathBuf::from(format!(
            "/tmp/openshelf-store-test-{}-{}.db",
            std::process::id(),
            now_ms()
        ));
        {
            let store = Store::open(&path).unwrap();
            create_svalbard_call(&store, "persistent-buyer", 1);
        }
        {
            let reopened = Store::open(&path).unwrap();
            let calls = reopened.list_open_calls(Some("persistent-buyer")).unwrap();
            assert!(calls.iter().any(|call| call.mine));
        }
        for suffix in ["", "-wal", "-shm"] {
            let _ = std::fs::remove_file(format!("{}{suffix}", path.display()));
        }
    }

    #[test]
    fn simultaneous_sqlite_cold_starts_serialize_schema_and_seed_work() {
        let path = std::env::temp_dir().join(format!(
            "openshelf-concurrent-migration-{}-{}.db",
            std::process::id(),
            new_id("cold-start")
        ));
        let barrier = Arc::new(Barrier::new(4));
        let workers = (0..4)
            .map(|_| {
                let path = path.clone();
                let barrier = Arc::clone(&barrier);
                std::thread::spawn(move || {
                    barrier.wait();
                    Store::open(path)
                })
            })
            .collect::<Vec<_>>();
        let stores = workers
            .into_iter()
            .map(|worker| worker.join().expect("cold-start worker should not panic"))
            .collect::<Result<Vec<_>, _>>()
            .expect("every simultaneous cold start should migrate successfully");
        assert!(stores.iter().all(|store| store.ready().is_ok()));
        assert!(
            stores[0]
                .documents()
                .unwrap()
                .iter()
                .any(|document| document.handle == "SEONGS_11")
        );
        drop(stores);
        for suffix in ["", "-wal", "-shm"] {
            let target = PathBuf::from(format!("{}{suffix}", path.display()));
            if target.exists() {
                std::fs::remove_file(&target).unwrap();
            }
        }
    }

    #[test]
